SELECT id,interval_code,candle_open_time,decision,total_score,confidence_score,latest_price,stop_loss,take_profit,final_entry_allowed,generated_at FROM trade_signal WHERE symbol='SHIBUSDT' AND ((interval_code='1m' AND generated_at >= '2026-10-09 23:54:00' AND generated_at < '2026-10-10 00:06:00') OR (interval_code='5m' AND generated_at >= '2026-10-09 23:45:00' AND generated_at < '2026-10-10 00:06:00') OR (interval_code='1h' AND generated_at >= '2026-10-09 21:00:00' AND generated_at < '2026-10-10 00:06:00')) ORDER BY generated_at,interval_code